// clavinet-v screens: the tone the rocker switches and the mute carve, and the vocal filter's A-E-I-O-U pad.
const BLUE = "#3d7dff", GREEN = "#3ec96b", WHITE = "#ffffff", ORANGE = "#ff6a1a", GREY = "#6b6b6b";
const FONT = "8px ui-monospace, monospace";
const BIG = "bold 16px ui-monospace, monospace";
const VOWELS = ["A", "E", "I", "O", "U"];

function text(ctx, s, x, y, c, align, font) {
  ctx.fillStyle = c;
  ctx.font = font || FONT;
  ctx.textAlign = align || "left";
  ctx.fillText(s, x, y);
}

const on = (v) => (v ?? 0) >= 0.5;
const lp = (f, fc) => 1 / Math.sqrt(1 + Math.pow(f / fc, 2));
const hp = (f, fc) => 1 / Math.sqrt(1 + Math.pow(fc / f, 2));

export default {
  tone_screen(lcd) {
    const { ctx, width: W, height: H, params: p, output } = lcd;
    ctx.fillStyle = "#000";
    ctx.fillRect(0, 0, W, H);
    const br = on(p["Tone Brillant"]), tr = on(p["Tone Treble"]), md = on(p["Tone Medium"]), sf = on(p["Tone Soft"]);
    const mute = p["Mute"] ?? 0;
    const resp = (f) => {
      let m = 1;
      if (br) m *= hp(f, 900);
      if (tr) m *= hp(f, 300);
      if (md) m *= 0.4 + 0.6 * Math.exp(-Math.pow(Math.log2(f / 900), 2));
      if (sf) m *= lp(f, 1200);
      m *= lp(f, 12000 * Math.pow(0.03, mute));
      return 20 * Math.log10(Math.max(m, 1e-4));
    };
    const top = 30, bot = H - 12;
    const y = (d) => top + (Math.min(0, Math.max(-36, d)) / -36) * (bot - top);
    ctx.strokeStyle = "#1a1a1a";
    ctx.beginPath(); ctx.moveTo(0, y(0)); ctx.lineTo(W, y(0)); ctx.stroke();
    ctx.strokeStyle = ORANGE;
    ctx.lineWidth = 1;
    ctx.beginPath();
    for (let x = 0; x <= W; x++) {
      const f = 40 * Math.pow(400, x / W), yy = y(resp(f));
      if (x === 0) ctx.moveTo(x, yy); else ctx.lineTo(x, yy);
    }
    ctx.stroke();
    ctx.fillStyle = "#ff6a1a40";
    ctx.beginPath();
    ctx.moveTo(0, bot);
    for (let x = 0; x <= W; x += 2) ctx.lineTo(x, y(resp(40 * Math.pow(400, x / W))));
    ctx.lineTo(W, bot);
    ctx.closePath();
    ctx.fill();
    const lights = [["BRILL", br], ["TREB", tr], ["MED", md], ["SOFT", sf]];
    lights.forEach(([s, lit], i) => text(ctx, s, 4 + i * 34, 9, lit ? ORANGE : GREY));
    const ab = on(p["Pickup A/B Switch"]) ? "B" : "A", cd = on(p["Pickup C/D Switch"]) ? "D" : "C";
    text(ctx, ab + cd, W - 4, 22, WHITE, "right", BIG);
    if (mute > 0.02) {
      ctx.fillStyle = BLUE;
      ctx.fillRect(4, 14, Math.max(2, mute * 60), 3);
      text(ctx, "MUTE", 68, 19, BLUE);
    }
    let lv = 0;
    if (output && output.length) for (let i = Math.max(0, output.length - 16); i < output.length; i++) lv = Math.max(lv, output[i] || 0);
    if (lv > 0.001) { ctx.fillStyle = GREEN; ctx.fillRect(W - 3, bot - lv * (bot - top), 2, lv * (bot - top)); }
    text(ctx, "LOW", 4, H - 2, GREY);
    text(ctx, "HIGH", W - 4, H - 2, GREY, "right");
  },

  vowel_screen(lcd) {
    const { ctx, width: W, height: H, params: p, now } = lcd;
    ctx.fillStyle = "#000";
    ctx.fillRect(0, 0, W, H);
    const live = on(p["Vocal Filter On/Off"]);
    const lfo = on(p["Vocal Filter LFO On/Off"]);
    const pad = 10, pw = W - pad * 2, ph = H - pad * 2 - 4;
    const pts = VOWELS.map((v, i) => {
      const dx = [0.15, 0.31, 0.73, 0.87, 0.48][i], dy = [0.65, 0.25, 0.23, 0.73, 0.85][i];
      return [pad + (p[`${v} Position X`] ?? dx) * pw, pad + 4 + (1 - (p[`${v} Position Y`] ?? dy)) * ph];
    });
    ctx.strokeStyle = "#1a1a1a";
    ctx.strokeRect(pad + 0.5, pad + 4.5, pw, ph);
    ctx.strokeStyle = live ? WHITE : GREY;
    ctx.lineWidth = 1;
    ctx.beginPath();
    pts.forEach(([x, yy], i) => (i === 0 ? ctx.moveTo(x, yy) : ctx.lineTo(x, yy)));
    ctx.closePath();
    ctx.stroke();
    pts.forEach(([x, yy], i) => {
      ctx.fillStyle = live ? BLUE : GREY;
      ctx.beginPath(); ctx.arc(x, yy, 3, 0, 2 * Math.PI); ctx.fill();
      text(ctx, VOWELS[i], x + 5, yy - 3, live ? WHITE : GREY);
    });
    if (live && lfo) {
      const rate = 0.1 + (p["Vocal Filter LFO rate"] ?? 0.6) * 2;
      const t = ((((now || 0) / 1000) * rate) % 1 + 1) % 1;
      const seg = t * 5, k = Math.min(4, Math.floor(seg)), f = seg - k;
      const a = pts[k], b = pts[(k + 1) % 5];
      ctx.fillStyle = ORANGE;
      ctx.beginPath(); ctx.arc(a[0] + (b[0] - a[0]) * f, a[1] + (b[1] - a[1]) * f, 4, 0, 2 * Math.PI); ctx.fill();
    }
    text(ctx, live ? (lfo ? "VOCAL LFO" : "VOCAL") : "VOCAL OFF", 4, 9, live ? WHITE : GREY);
  },
};

// stage-73-v2 screens: the tine swinging past its pickup with the wave it makes, and the stereo vibrato.
const FONT = "8px ui-monospace, monospace";
const BLUE = "#3d7dff";
const GREEN = "#3ec96b";
const ORANGE = "#ff6a1a";
const WHITE = "#ffffff";
const GREY = "#6b6b6b";

function clamp01(v) {
  return Number.isFinite(v) ? Math.min(1, Math.max(0, v)) : 0;
}

function last(arr) {
  return Array.isArray(arr) && arr.length > 0 ? clamp01(arr[arr.length - 1] ?? 0) : 0;
}

export default {
  pickup_screen(lcd) {
    const { ctx, width: W, height: H, params, output, now } = lcd;
    ctx.fillStyle = "#000";
    ctx.fillRect(0, 0, W, H);
    ctx.font = FONT;
    const hard = clamp01(params["Hammer Hardness"] ?? 0.65);
    const dist = clamp01(params["Pickup Distance"] ?? 0.42);
    const align = clamp01(params["Pickup Alignment"] ?? 0.6);
    const level = last(output);
    const t = (now ?? 0) / 1000;
    // Top half: the tine, its swing, and the pickup coil set back by distance and offset by alignment.
    const mid = H * 0.3;
    const tipX = W * 0.55;
    const swing = (0.25 + level * 0.75) * H * 0.12;
    const tipY = mid + Math.sin(t * 20) * (level > 0.001 ? swing : 0);
    ctx.strokeStyle = WHITE;
    ctx.lineWidth = 1;
    ctx.beginPath();
    ctx.moveTo(6, mid);
    ctx.lineTo(tipX, tipY);
    ctx.stroke();
    ctx.strokeStyle = GREY;
    ctx.beginPath();
    ctx.moveTo(tipX, mid - swing);
    ctx.lineTo(tipX, mid + swing);
    ctx.stroke();
    const coilX = tipX + 6 + dist * W * 0.3;
    const coilY = mid + (align - 0.5) * H * 0.3;
    const cw = Math.max(6, W * 0.08);
    const ch = Math.max(8, H * 0.22);
    ctx.fillStyle = BLUE;
    ctx.fillRect(coilX, coilY - ch / 2, cw, ch);
    ctx.strokeStyle = ORANGE;
    ctx.beginPath();
    ctx.arc(10, mid - 6, 2 + hard * 4, 0, Math.PI * 2);
    ctx.stroke();
    // Bottom half: the voltage the coil sees — asymmetric as the tine sits off-axis, softer as it moves away.
    const wy = H * 0.72;
    const amp = Math.max(2, H * 0.18) * (1 - dist * 0.6);
    const off = (align - 0.5) * 2;
    ctx.strokeStyle = GREEN;
    ctx.beginPath();
    const n = 96;
    for (let i = 0; i <= n; i++) {
      const p = (i / n) * Math.PI * 6;
      const s = Math.sin(p);
      const v = s + off * 0.6 * (s * s - 0.5) + hard * 0.15 * Math.sin(3 * p);
      const x = 4 + ((W - 8) * i) / n;
      const y = wy - Math.max(-1.4, Math.min(1.4, v)) * amp * 0.75;
      if (i === 0) ctx.moveTo(x, y);
      else ctx.lineTo(x, y);
    }
    ctx.stroke();
    ctx.fillStyle = ORANGE;
    ctx.fillText("HAMMER", 4, H - 3);
    ctx.fillStyle = BLUE;
    ctx.textAlign = "right";
    ctx.fillText("PICKUP", W - 4, H - 3);
    ctx.textAlign = "left";
  },

  vib_screen(lcd) {
    const { ctx, width: W, height: H, params, now, output } = lcd;
    ctx.fillStyle = "#000";
    ctx.fillRect(0, 0, W, H);
    ctx.font = FONT;
    const on = (params["Preamp Vibrato On"] ?? 0) >= 0.5;
    const depth = clamp01(params["Preamp Vibrato Intensity"] ?? 0);
    const rate = clamp01(params["Preamp Vibrato Speed"] ?? 0.5);
    const cycles = 1 + rate * 5;
    const top = 12;
    const bottom = H - 12;
    const mid = (top + bottom) / 2;
    const half = Math.max(1, (bottom - top) / 2);
    const amp = on ? depth * half : 0;
    const phase = output && output.length > 0 && on ? ((now ?? 0) / 1000) * (1 + rate * 6) : 0;
    const wave = (sign, color) => {
      ctx.strokeStyle = color;
      ctx.beginPath();
      const n = 64;
      for (let i = 0; i <= n; i++) {
        const x = 4 + ((W - 8) * i) / n;
        const y = mid - sign * Math.sin((i / n) * cycles * Math.PI * 2 + phase) * amp;
        if (i === 0) ctx.moveTo(x, y);
        else ctx.lineTo(x, y);
      }
      ctx.stroke();
    };
    ctx.strokeStyle = GREY;
    ctx.beginPath();
    ctx.moveTo(4, Math.round(mid) + 0.5);
    ctx.lineTo(W - 4, Math.round(mid) + 0.5);
    ctx.stroke();
    wave(1, on ? GREEN : GREY);
    wave(-1, on ? WHITE : GREY);
    ctx.fillStyle = on ? GREEN : GREY;
    ctx.fillText("L", 4, 9);
    ctx.fillStyle = on ? WHITE : GREY;
    ctx.fillText("R", 12, 9);
    ctx.textAlign = "right";
    ctx.fillStyle = on ? WHITE : GREY;
    ctx.fillText(on ? "VIBRATO" : "VIB OFF", W - 4, 9);
    ctx.textAlign = "left";
  },
};

// Screens for Wurli V2: the struck reed, the graphic EQ's curve, the Leslie's rotors.
const BLUE = "#3d7dff", GREEN = "#3ec96b", WHITE = "#ffffff", ORANGE = "#ff6a1a", RED = "#ff3b30", GREY = "#6b6b6b";
const FONT = "8px ui-monospace, monospace";

const clamp = (v, a, b) => Math.min(b, Math.max(a, v));
const num = (v, d) => (typeof v === "number" && isFinite(v) ? v : d);
const last = (arr) => (Array.isArray(arr) && arr.length ? num(arr[arr.length - 1], 0) : 0);

function glass(ctx, W, H) {
  ctx.fillStyle = "#000";
  ctx.fillRect(0, 0, W, H);
  ctx.lineWidth = 1;
  ctx.font = FONT;
  ctx.textBaseline = "top";
}

function tag(ctx, text, x, y, color) {
  ctx.fillStyle = color;
  ctx.fillText(text, x, y);
}

export default {
  reed(lcd) {
    const { ctx, width: W, height: H, params, output, state } = lcd;
    glass(ctx, W, H);
    const hard = clamp(num(params["Hammer Hardness"], 0.5), 0, 1);
    const damp = clamp(num(params["Damping Duration"], 0.4), 0, 1);
    const dist = clamp(num(params["Pickup Distance"], 0.5), 0, 1);
    const axis = clamp(num(params["Pickup Axis"], 0.5), 0, 1);
    const trem = clamp(num(params["Tremolo"], 0), 0, 1);
    // The reed on the left third: clamped at its root, the tip swinging with the output level.
    const rw = Math.max(20, W * 0.3), cy = H * 0.55;
    const lvl = clamp(last(output) * 3, 0, 1);
    state.swing = num(state.swing, 0) * 0.6 + lvl * 0.4;
    const tipY = cy - state.swing * H * 0.25;
    ctx.fillStyle = GREY;
    ctx.fillRect(4, cy - 6, 5, 12);
    ctx.strokeStyle = WHITE;
    ctx.beginPath();
    ctx.moveTo(9, cy);
    ctx.quadraticCurveTo(rw * 0.6, cy, rw, tipY);
    ctx.stroke();
    // The pickup comb: nearer the reed for a smaller distance, offset up or down by the axis.
    const gap = 4 + dist * 14, off = (axis - 0.5) * 16;
    ctx.strokeStyle = ORANGE;
    ctx.beginPath();
    ctx.moveTo(rw - 8, cy + gap + off);
    ctx.lineTo(rw + 8, cy + gap + off);
    ctx.moveTo(rw - 8, cy - gap + off);
    ctx.lineTo(rw + 8, cy - gap + off);
    ctx.stroke();
    // The hammer: a blue dot whose size is its hardness.
    ctx.fillStyle = BLUE;
    ctx.beginPath();
    ctx.arc(rw * 0.55, cy + 10, 2 + hard * 4, 0, Math.PI * 2);
    ctx.fill();
    // The note it rings: harder hammer = more harmonics, closer pickup = more asymmetric bark.
    const x0 = rw + 16, x1 = W - 4, mid = H * 0.5, amp = H * 0.36;
    const asym = (1 - dist) * 0.8, h3 = hard * 0.5, tau = 0.15 + damp * 0.85;
    ctx.strokeStyle = GREY;
    ctx.beginPath();
    ctx.moveTo(x0, mid);
    ctx.lineTo(x1, mid);
    ctx.stroke();
    ctx.strokeStyle = WHITE;
    ctx.beginPath();
    const n = Math.max(2, Math.floor(x1 - x0));
    for (let i = 0; i <= n; i++) {
      const t = i / n;
      const env = Math.exp(-t / tau) * (1 - trem * 0.4 * (1 + Math.sin(t * 30)) * 0.5);
      const s = Math.sin(t * 2 * Math.PI * 9);
      const y = (s + h3 * Math.sin(t * 2 * Math.PI * 27) + asym * s * s - asym * 0.5) / (1 + h3 + asym * 0.5);
      const px = x0 + i, py = mid - y * env * amp;
      if (i === 0) ctx.moveTo(px, py);
      else ctx.lineTo(px, py);
    }
    ctx.stroke();
    tag(ctx, "REED", 4, 3, GREY);
    tag(ctx, "HAMMER", 4, H - 11, BLUE);
    tag(ctx, "PICKUP", Math.max(4, W - 40), H - 11, ORANGE);
  },

  eq_curve(lcd) {
    const { ctx, width: W, height: H, params } = lcd;
    glass(ctx, W, H);
    const bands = [
      ["32 Hz low shelf gain", 32, "low"],
      ["63 Hz peak gain", 63, "peak"],
      ["125 Hz peak gain", 125, "peak"],
      ["250 Hz peak gain", 250, "peak"],
      ["500 Hz peak gain", 500, "peak"],
      ["1 kHz peak gain", 1000, "peak"],
      ["2 kHz peak gain", 2000, "peak"],
      ["4 kHz peak gain", 4000, "peak"],
      ["8 kHz peak gain", 8000, "peak"],
      ["16 kHz high shelf gain", 16000, "high"],
    ].map(([name, f, kind]) => ({ f, kind, g: (clamp(num(params[name], 0.5), 0, 1) - 0.5) * 2 }));
    const lo = Math.log2(20), hi = Math.log2(20000);
    const xOf = (f) => ((Math.log2(f) - lo) / (hi - lo)) * (W - 8) + 4;
    const mid = H / 2, span = H * 0.4;
    const gainAt = (f) => {
      let g = 0;
      for (const b of bands) {
        const d = Math.log2(f / b.f);
        if (b.kind === "low") g += b.g / (1 + Math.exp(d * 4));
        else if (b.kind === "high") g += b.g / (1 + Math.exp(-d * 4));
        else g += b.g * Math.exp(-(d * d) / 0.5);
      }
      return clamp(g, -1, 1);
    };
    ctx.strokeStyle = GREY;
    ctx.beginPath();
    ctx.moveTo(4, mid);
    ctx.lineTo(W - 4, mid);
    ctx.stroke();
    ctx.strokeStyle = WHITE;
    ctx.beginPath();
    for (let x = 4; x <= W - 4; x++) {
      const f = Math.pow(2, lo + ((x - 4) / Math.max(1, W - 8)) * (hi - lo));
      const y = mid - gainAt(f) * span;
      if (x === 4) ctx.moveTo(x, y);
      else ctx.lineTo(x, y);
    }
    ctx.stroke();
    for (const b of bands) {
      const x = xOf(b.f);
      ctx.fillStyle = b.g === 0 ? GREY : ORANGE;
      ctx.beginPath();
      ctx.arc(x, mid - b.g * span, 2, 0, Math.PI * 2);
      ctx.fill();
    }
    tag(ctx, "EQ", 4, 3, GREY);
  },

  rotor(lcd) {
    const { ctx, width: W, height: H, params, output, state, now } = lcd;
    glass(ctx, W, H);
    const speed = num(params["Leslie Speed"], 0.5);
    const rate = clamp(num(params["Leslie Rate"], 0.5), 0, 1);
    const depth = clamp(num(params["Leslie High - depth"], 0.5), 0, 1);
    const width = clamp(num(params["Leslie High - width"], 0.5), 0, 1);
    const mode = speed < 0.25 ? 0 : speed < 0.75 ? 1 : 2;
    const rps = [0, 0.8, 6.5][mode] * (0.5 + rate);
    // Turn only while sound is moving; otherwise hold the last angle.
    const t = num(now, 0) / 1000;
    const moving = last(output) > 0.001;
    if (moving) state.angle = num(state.angle, 0) + rps * Math.max(0, Math.min(0.1, t - num(state.t, t))) * Math.PI * 2;
    state.t = t;
    const a = num(state.angle, 0.6);
    const r = Math.max(6, Math.min(H * 0.38, W * 0.2));
    const hx = W * 0.3, dx = W * 0.7, cy = H * 0.5;
    ctx.strokeStyle = GREY;
    ctx.beginPath();
    ctx.arc(hx, cy, r, 0, Math.PI * 2);
    ctx.stroke();
    ctx.beginPath();
    ctx.arc(dx, cy, r, 0, Math.PI * 2);
    ctx.stroke();
    // The horn: two bells, their length the depth, the throw spread by the width.
    const hl = r * (0.4 + depth * 0.6);
    ctx.strokeStyle = WHITE;
    ctx.beginPath();
    ctx.moveTo(hx - Math.cos(a) * hl, cy - Math.sin(a) * hl);
    ctx.lineTo(hx + Math.cos(a) * hl, cy + Math.sin(a) * hl);
    ctx.stroke();
    ctx.fillStyle = ORANGE;
    ctx.beginPath();
    ctx.arc(hx + Math.cos(a) * hl, cy + Math.sin(a) * hl, 2 + width * 3, 0, Math.PI * 2);
    ctx.fill();
    // The drum turns slower, the other way.
    const b = -a * 0.8;
    ctx.fillStyle = BLUE;
    ctx.beginPath();
    ctx.moveTo(dx, cy);
    ctx.arc(dx, cy, r * 0.8, b, b + Math.PI * 0.6);
    ctx.closePath();
    ctx.fill();
    tag(ctx, "HORN", 4, 3, GREY);
    tag(ctx, "DRUM", Math.max(4, W - 28), 3, GREY);
    tag(ctx, ["STOP", "SLOW", "FAST"][mode], 4, H - 11, mode === 2 ? RED : mode === 1 ? GREEN : GREY);
  },
};
